import { memo, useEffect, useRef, useState, type ComponentType } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { SiteModelConfig } from '../../config/schema';
import { disposeModelRoot } from '../devices/deviceModel';
import { PointerTap } from '../devices/pointer-tap';
import { findHotspotId, loadSiteModel, type LoadedSiteModel, type SiteHotspotRuntime } from './siteModel';

export interface SiteMarkerConfig {
  id: string;
  label: string;
  description: string;
}

export interface SiteViewState {
  /** 每次自增即复位视角。 */
  reset: number;
  rotate: boolean;
  top: boolean;
  /** 聚焦到某台设备（点击卡片时用），null 表示不聚焦。 */
  focus: string | null;
}

export interface SiteSceneProps {
  site: SiteModelConfig;
  markers: SiteMarkerConfig[];
  view: SiteViewState;
  onActivate(hotspotId: string): void;
  onProgress?(percent: number): void;
  onError?(message: string): void;
  onIssues?(count: number): void;
  onReady?(): void;
  retryToken?: number;
}

export type SiteSceneComponent = ComponentType<SiteSceneProps>;

/** 户外天空色：场地模型是露天的，浅灰蓝底比纯白底更能拉开层次。 */
const SKY = new THREE.Color('#dde5e9');

function fitDistance(size: THREE.Vector3, fovDegrees: number, aspect: number) {
  const vertical = THREE.MathUtils.degToRad(fovDegrees);
  const heightDistance = size.y / (2 * Math.tan(vertical / 2));
  const widthDistance = size.x / (2 * Math.tan(vertical / 2) * Math.max(0.2, aspect));
  return Math.max(heightDistance, widthDistance, size.z * 0.6) * 1.25;
}

export const SiteScene = memo(function SiteScene({
  site,
  markers,
  view,
  onActivate,
  onProgress,
  onError,
  onIssues,
  onReady,
  retryToken = 0,
}: SiteSceneProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const markerRefs = useRef(new Map<string, HTMLButtonElement>());
  const viewRef = useRef(view);
  const activateRef = useRef(onActivate);
  const progressRef = useRef(onProgress);
  const errorRef = useRef(onError);
  const issuesRef = useRef(onIssues);
  const readyRef = useRef(onReady);
  const [progress, setProgress] = useState<number | null>(null);
  const [preparing, setPreparing] = useState(false);
  const [ready, setReady] = useState(false);
  const [loadError, setLoadError] = useState('');
  const [retryAttempt, setRetryAttempt] = useState(0);

  viewRef.current = view;
  activateRef.current = onActivate;
  progressRef.current = onProgress;
  errorRef.current = onError;
  issuesRef.current = onIssues;
  readyRef.current = onReady;

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    let disposed = false;
    let animationFrame = 0;
    let dirty = true;
    let ready = false;
    let loaded: LoadedSiteModel | null = null;
    let contextIsLost = false;
    let restoreFallback = 0;
    let lastView = '';
    let lastReset = -1;
    let lastFocus: string | null = null;
    let tween: { from: THREE.Vector3; to: THREE.Vector3; targetFrom: THREE.Vector3; targetTo: THREE.Vector3; t: number } | null = null;
    const clock = new THREE.Clock();
    const maxPixelRatio = Math.min(window.devicePixelRatio, 1.5);
    let pixelRatio = maxPixelRatio;
    let renderedFrames = 0;
    let renderedSeconds = 0;

    setProgress(null);
    setPreparing(false);
    setReady(false);
    setLoadError('');

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ antialias: false, alpha: false, powerPreference: 'high-performance' });
    } catch {
      const message = '无法启动三维查看器，请使用支持 WebGL 的浏览器';
      setLoadError(message);
      errorRef.current?.(message);
      return;
    }

    renderer.setClearColor(SKY, 1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.05;
    renderer.domElement.setAttribute('aria-label', '库外试验场三维场地模型。拖动旋转，滚轮或双指缩放，点击设备进入三维详情。');
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = SKY.clone();
    // 默认取景距离约 370 m（整场 388 × 137 m），雾的近端必须比它更远，
    // 否则一进场整片场地都是灰的；远端留到 2.2 km，只让最远的那一角淡出去。
    scene.fog = new THREE.Fog(SKY.clone(), 520, 2200);
    // 场地跨度近 400 米，近裁剪面必须放大（1 厘米级近裁剪会让 400 米外的深度精度崩掉）。
    const camera = new THREE.PerspectiveCamera(45, 1, 0.6, 2600);
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.09;
    controls.enablePan = true;
    controls.screenSpacePanning = true;
    // 桌面端操作：左键旋转、**中键平移**、右键也保留平移（老习惯），滚轮缩放。
    // OrbitControls 默认是中键 dolly、右键平移，这里按需求把平移挪到中键。
    controls.mouseButtons = { LEFT: THREE.MOUSE.ROTATE, MIDDLE: THREE.MOUSE.PAN, RIGHT: THREE.MOUSE.PAN };
    controls.minDistance = 3;
    controls.maxDistance = 900;
    controls.maxPolarAngle = Math.PI * 0.495;
    controls.zoomSpeed = 0.9;
    controls.rotateSpeed = 0.55;
    controls.addEventListener('change', () => { dirty = true; });

    const pmrem = new THREE.PMREMGenerator(renderer);
    const room = new RoomEnvironment();
    const environment = pmrem.fromScene(room, 0.05);
    scene.environment = environment.texture;
    room.dispose();
    pmrem.dispose();
    scene.add(new THREE.HemisphereLight(0xf2f7fa, 0x9aa3a6, 1.15));
    const keyLight = new THREE.DirectionalLight(0xfff6e8, 1.85);
    keyLight.position.set(-120, 220, 160);
    scene.add(keyLight);
    const fillLight = new THREE.DirectionalLight(0xdfeaf5, 0.75);
    fillLight.position.set(180, 90, -140);
    scene.add(fillLight);

    const modelRoot = new THREE.Group();
    modelRoot.name = 'site-root';
    scene.add(modelRoot);

    // 性能探针（只有 `?perf=1` 时挂载）：场地是全站最重的一屏，验证时要能读到真实的
    // draw call / 贴图显存 / 三角面数，而不是只看帧率。
    if (new URLSearchParams(window.location.search).get('perf') === '1') {
      (window as unknown as { __museumSite?: unknown }).__museumSite = { renderer, scene, camera, modelRoot, controls };
    }

    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    const tap = new PointerTap();

    // 中键平移的配套处理：Chrome 在画布上按中键会弹出"自动滚动"圆盘抢走拖拽，
    // OrbitControls 自己不会 preventDefault（它只监听 pointer 事件），这里按掉 mousedown 的默认行为。
    const suppressMiddleButtonDefault = (event: MouseEvent) => {
      if (event.button === 1) event.preventDefault();
    };
    renderer.domElement.addEventListener('mousedown', suppressMiddleButtonDefault);
    renderer.domElement.addEventListener('auxclick', suppressMiddleButtonDefault);

    const setCamera = (target: THREE.Vector3, position: THREE.Vector3) => {
      controls.target.copy(target);
      camera.position.copy(position);
      controls.update();
      dirty = true;
    };

    const boundsOf = (objects: THREE.Object3D[]) => {
      const bounds = new THREE.Box3();
      for (const object of objects) {
        object.updateWorldMatrix(true, true);
        bounds.expandByObject(object, true);
      }
      return bounds;
    };

    const fitAll = () => {
      const bounds = new THREE.Box3().setFromObject(modelRoot);
      if (bounds.isEmpty()) return;
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      const distance = fitDistance(size, camera.fov, camera.aspect);
      // 默认视线：从场地南侧偏东俯视（场地按 y 轴铺开，z 向上）。
      const direction = new THREE.Vector3(0.45, 0.52, 0.72).normalize();
      setCamera(center, center.clone().addScaledVector(direction, distance));
    };

    /** 聚焦一台设备：把相机拉到该设备包围盒外，做一段补间而不是瞬移。 */
    const makeFocusTween = (hotspot: SiteHotspotRuntime) => {
      const bounds = hotspot.objects.length ? boundsOf(hotspot.objects) : new THREE.Box3();
      if (hotspot.objects.length === 0) bounds.expandByPoint(hotspot.anchor);
      const center = bounds.isEmpty() ? hotspot.anchor.clone() : bounds.getCenter(new THREE.Vector3());
      const size = bounds.isEmpty() ? new THREE.Vector3(12, 12, 12) : bounds.getSize(new THREE.Vector3());
      const distance = Math.max(18, fitDistance(size, camera.fov, camera.aspect) * 1.15);
      const direction = new THREE.Vector3(0.5, 0.45, 0.74).normalize();
      return {
        from: camera.position.clone(),
        to: center.clone().addScaledVector(direction, distance),
        targetFrom: controls.target.clone(),
        targetTo: center,
        t: 0,
      };
    };

    const project = (anchor: THREE.Vector3) => {
      const point = anchor.clone().project(camera);
      const width = host.clientWidth;
      const height = host.clientHeight;
      return {
        x: (point.x * 0.5 + 0.5) * width,
        y: (-point.y * 0.5 + 0.5) * height,
        visible: point.z < 1 && point.x > -1.35 && point.x < 1.35 && point.y > -1.35 && point.y < 1.35,
      };
    };

    /**
     * 面板遮挡：标记层在画布之上、面板之下，被右侧设备列表/工具条/身份区盖住的标记只剩下
     * 一条白边从卡片边缘探出来，看着像渲染错位（实测 844×390 时 93% 被卡片盖住）。
     * 这类标记本来也点不到，所以整块隐藏；旋转视角离开面板后自动恢复。
     */
    const overlayRects: Array<{ left: number; top: number; right: number; bottom: number }> = [];
    const markerSizes = new Map<string, { width: number; height: number }>();
    const refreshOverlays = () => {
      overlayRects.length = 0;
      markerSizes.clear();
      for (const [id, element] of markerRefs.current) {
        markerSizes.set(id, { width: element.offsetWidth, height: element.offsetHeight });
      }
      const parent = host.parentElement;
      if (!parent) return;
      const hostRect = host.getBoundingClientRect();
      for (const name of ['site-device-rail', 'site-tools', 'site-identity']) {
        const element = parent.querySelector<HTMLElement>(`.${name}`);
        if (!element || element.offsetParent === null) continue;
        const rect = element.getBoundingClientRect();
        if (!rect.width || !rect.height) continue;
        overlayRects.push({
          left: rect.left - hostRect.left,
          top: rect.top - hostRect.top,
          right: rect.right - hostRect.left,
          bottom: rect.bottom - hostRect.top,
        });
      }
    };
    /** 标记盒子被面板盖住的比例。 */
    const coveredRatio = (box: { left: number; top: number; right: number; bottom: number }) => {
      const area = Math.max(1, (box.right - box.left) * (box.bottom - box.top));
      let covered = 0;
      for (const rect of overlayRects) {
        const wide = Math.min(box.right, rect.right) - Math.max(box.left, rect.left);
        const tall = Math.min(box.bottom, rect.bottom) - Math.max(box.top, rect.top);
        if (wide > 0 && tall > 0) covered += wide * tall;
      }
      return covered / area;
    };

    const updateMarkers = () => {
      if (!loaded) return;
      for (const hotspot of loaded.hotspots) {
        const element = markerRefs.current.get(hotspot.config.id);
        if (!element) continue;
        const { x, y, visible } = project(hotspot.anchor);
        element.style.transform = `translate(-50%, -100%) translate(${Math.round(x)}px, ${Math.round(y)}px)`;
        const size = markerSizes.get(hotspot.config.id);
        // 尺寸还没量出来（首帧 / jsdom 里布局为 0）时不做遮挡判断，只按可见性显示。
        const occluded = size && size.width > 4 && size.height > 4
          ? coveredRatio({ left: x - size.width / 2, right: x + size.width / 2, top: y - size.height, bottom: y }) >= 0.5
          : false;
        element.style.visibility = visible && !occluded ? 'visible' : 'hidden';
      }
    };

    const prepareStaticRoot = (root: THREE.Object3D) => {
      root.traverse(object => {
        object.updateMatrix();
        object.matrixAutoUpdate = false;
        const mesh = object as THREE.Mesh;
        if (mesh.isMesh) mesh.geometry.computeBoundingSphere();
      });
      root.updateMatrixWorld(true);
    };

    const resize = () => {
      refreshOverlays();
      if (!host.clientWidth || !host.clientHeight) return;
      renderer.setPixelRatio(pixelRatio);
      camera.aspect = host.clientWidth / host.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(host.clientWidth, host.clientHeight);
      dirty = true;
    };
    const observer = new ResizeObserver(resize);
    observer.observe(host);
    // 面板自己变形（例如身份区多出一行提示、设备列表高度变化）也要重算遮挡矩形，
    // 否则缓存的矩形会过期，标记可能该隐藏的没隐藏。
    const panelObserver = new ResizeObserver(() => refreshOverlays());
    for (const selector of ['site-device-rail', 'site-tools', 'site-identity']) {
      const element = host.parentElement?.querySelector(selector);
      if (element) panelObserver.observe(element);
    }
    resize();

    loadSiteModel(site, {
      onProgress: value => {
        if (disposed) return;
        // GLTFLoader 的 100% 仅代表文件下载完成；Draco 解码和首帧渲染仍需时间。
        if (value >= 100) setPreparing(true);
        else setProgress(Math.max(0, Math.min(99, value)));
        progressRef.current?.(Math.min(99, value));
      },
    }).then(model => {
      if (disposed) {
        disposeModelRoot(model.root);
        return;
      }
      setPreparing(true);
      loaded = model;
      modelRoot.add(model.root);
      // 静态场景：关掉每帧的世界矩阵重算（1447 个网格时这是实打实的 CPU 开销），
      // 这里一次性算好即可——场地模型不会动。
      prepareStaticRoot(modelRoot);
      modelRoot.updateMatrixWorld(true);
      issuesRef.current?.(model.issues.length);
      ready = true;
      fitAll();
      // 标记尺寸与面板矩形要在同一帧刷新（面板布局此时已定型），再据此决定标记是否被盖住。
      refreshOverlays();
      updateMarkers();
      dirty = true;
      // 先画出完整模型，再撤下不透明的加载层，避免闪过一帧空场景。
      renderer.render(scene, camera);
      dirty = false;
      progressRef.current?.(100);
      setReady(true);
      onReady?.();
    }).catch(error => {
      if (disposed) return;
      const message = error instanceof Error ? error.message : '场地模型加载失败';
      setLoadError(message);
      errorRef.current?.(message);
    });

    const pick = (clientX: number, clientY: number) => {
      if (!ready || !loaded) return null;
      // 只对"带热点的节点"做射线检测：场地模型合并后环境是一个上百万面的大网格，
      // 整场拾取每次都要几十毫秒；而这里真正只关心"有没有点到某台设备"。
      const roots = loaded.hotspots.flatMap(hotspot => hotspot.objects);
      if (!roots.length) return null;
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.set((clientX - rect.left) / rect.width * 2 - 1, -(clientY - rect.top) / rect.height * 2 + 1);
      raycaster.setFromCamera(pointer, camera);
      for (const hit of raycaster.intersectObjects(roots, true)) {
        const id = findHotspotId(hit.object, modelRoot, loaded.hotspots);
        if (id) return id;
      }
      return null;
    };

    const pointerDown = (event: PointerEvent) => {
      tap.down(event.pointerId, event.clientX, event.clientY, event.pointerType === 'touch' ? 12 : 5);
    };
    let lastHoverPick = 0;
    const pointerMove = (event: PointerEvent) => {
      tap.move(event.pointerId, event.clientX, event.clientY);
      if (event.pointerType === 'touch' || event.buttons !== 0) return;
      const now = performance.now();
      // 拾取只针对设备节点（见 pick），成本与场地环境的面数无关；这里仍限流到 8Hz。
      if (now - lastHoverPick < 120) return;
      lastHoverPick = now;
      renderer.domElement.style.cursor = pick(event.clientX, event.clientY) ? 'pointer' : 'grab';
    };
    const pointerUp = (event: PointerEvent) => {
      if (!tap.up(event.pointerId, event.clientX, event.clientY)) return;
      const id = pick(event.clientX, event.clientY);
      if (id) activateRef.current(id);
    };
    const pointerCancel = (event: PointerEvent) => tap.cancel(event.pointerId);
    renderer.domElement.addEventListener('pointerdown', pointerDown);
    renderer.domElement.addEventListener('pointermove', pointerMove);
    renderer.domElement.addEventListener('pointerup', pointerUp);
    renderer.domElement.addEventListener('pointercancel', pointerCancel);

    const contextLost = (event: Event) => {
      event.preventDefault();
      contextIsLost = true;
      renderer.domElement.style.opacity = '0';
      if (restoreFallback === 0) {
        restoreFallback = window.setTimeout(() => {
          restoreFallback = 0;
          if (disposed) return;
          contextIsLost = false;
          setRetryAttempt(value => value + 1);
        }, 600);
      }
    };
    const contextRestored = () => {
      contextIsLost = false;
      if (restoreFallback !== 0) {
        window.clearTimeout(restoreFallback);
        restoreFallback = 0;
      }
      setRetryAttempt(value => value + 1);
    };
    renderer.domElement.addEventListener('webglcontextlost', contextLost);
    renderer.domElement.addEventListener('webglcontextrestored', contextRestored);

    /** 俯视：从正上方看整场（场地是平面布局，俯视最适合找设备）。 */
    const topTween = () => {
      const bounds = new THREE.Box3().setFromObject(modelRoot);
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      const distance = fitDistance(size, camera.fov, camera.aspect);
      return {
        from: camera.position.clone(),
        to: center.clone().add(new THREE.Vector3(0, 0.02, 1).multiplyScalar(distance)),
        targetFrom: controls.target.clone(),
        targetTo: center,
        t: 0,
      };
    };

    const isoTween = () => {
      const bounds = new THREE.Box3().setFromObject(modelRoot);
      const center = bounds.getCenter(new THREE.Vector3());
      const size = bounds.getSize(new THREE.Vector3());
      const distance = fitDistance(size, camera.fov, camera.aspect);
      return {
        from: camera.position.clone(),
        to: center.clone().addScaledVector(new THREE.Vector3(0.45, 0.52, 0.72).normalize(), distance),
        targetFrom: controls.target.clone(),
        targetTo: center,
        t: 0,
      };
    };

    /** 把 view 状态翻译成相机动作：复位瞬移，俯视/等轴/聚焦走补间。 */
    const applyView = () => {
      const state = viewRef.current;
      if (!ready) return;
      if (state.reset !== lastReset) {
        lastReset = state.reset;
        lastView = state.top ? 'top' : 'iso';
        tween = null;
        if (state.top) {
          const target = topTween();
          setCamera(target.targetTo, target.to);
        } else {
          fitAll();
        }
      } else if (state.top !== (lastView === 'top')) {
        lastView = state.top ? 'top' : 'iso';
        tween = state.top ? topTween() : isoTween();
      }
      if (state.focus !== lastFocus) {
        lastFocus = state.focus;
        const hotspot = state.focus ? loaded?.hotspots.find(item => item.config.id === state.focus) : undefined;
        if (hotspot) tween = makeFocusTween(hotspot);
      }
    };

    const animate = () => {
      if (disposed) return;
      animationFrame = requestAnimationFrame(animate);
      if (contextIsLost) return;
      // 切到底部导航其它栏目时本页仍然挂载（模型不重载，切回来不用等），
      // 但外层槽位被 hidden 折叠成 0×0：这一帧直接跳过，别在看不见的画布上白渲染。
      // delta 本来就上限 0.05，所以切回来也不会"跳一帧"。
      if (!host.clientWidth || !host.clientHeight) return;
      const frameSeconds = clock.getDelta();
      const delta = Math.min(frameSeconds, 0.05);
      const state = viewRef.current;
      applyView();
      if (tween) {
        tween.t = Math.min(1, tween.t + delta / 0.75);
        const eased = tween.t < 0.5 ? 2 * tween.t * tween.t : 1 - 2 * (1 - tween.t) * (1 - tween.t);
        camera.position.lerpVectors(tween.from, tween.to, eased);
        controls.target.lerpVectors(tween.targetFrom, tween.targetTo, eased);
        dirty = true;
        if (tween.t >= 1) tween = null;
      }
      controls.autoRotate = ready && state.rotate;
      controls.autoRotateSpeed = 0.35;
      controls.update();
      if (controls.autoRotate) dirty = true;
      updateMarkers();
      if (dirty) {
        renderer.render(scene, camera);
        dirty = false;
        // Keep the complete geometry on screen. On a slow phone only the
        // framebuffer resolution changes, so buildings never pop in or out.
        if (ready && frameSeconds < 0.2 && maxPixelRatio > 1 && (navigator.maxTouchPoints > 0 || host.clientWidth < 700)) {
          renderedFrames += 1;
          renderedSeconds += frameSeconds;
          if (renderedFrames >= 45) {
            const averageMs = renderedSeconds * 1000 / renderedFrames;
            const next = averageMs > 36
              ? Math.max(1, pixelRatio - 0.25)
              : averageMs < 22 ? Math.min(maxPixelRatio, pixelRatio + 0.25) : pixelRatio;
            renderedFrames = 0;
            renderedSeconds = 0;
            if (next !== pixelRatio) {
              pixelRatio = next;
              renderer.setPixelRatio(pixelRatio);
              renderer.setSize(host.clientWidth, host.clientHeight, false);
              dirty = true;
            }
          }
        }
      }
    };
    animate();

    return () => {
      disposed = true;
      cancelAnimationFrame(animationFrame);
      if (restoreFallback !== 0) window.clearTimeout(restoreFallback);
      observer.disconnect();
      panelObserver.disconnect();
      controls.dispose();
      renderer.domElement.removeEventListener('pointerdown', pointerDown);
      renderer.domElement.removeEventListener('pointermove', pointerMove);
      renderer.domElement.removeEventListener('pointerup', pointerUp);
      renderer.domElement.removeEventListener('pointercancel', pointerCancel);
      renderer.domElement.removeEventListener('webglcontextlost', contextLost);
      renderer.domElement.removeEventListener('webglcontextrestored', contextRestored);
      renderer.domElement.removeEventListener('mousedown', suppressMiddleButtonDefault);
      renderer.domElement.removeEventListener('auxclick', suppressMiddleButtonDefault);
      if (loaded) disposeModelRoot(loaded.root);
      environment.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    };
  }, [site, retryAttempt, retryToken]);

  return (
    <div className="site-scene" ref={hostRef}>
      <div className="site-marker-layer">
        {markers.map(marker => (
          <button
            key={marker.id}
            type="button"
            className="site-marker"
            ref={element => {
              if (element) markerRefs.current.set(marker.id, element);
              else markerRefs.current.delete(marker.id);
            }}
            style={{ visibility: 'hidden' }}
            aria-label={`${marker.label}：查看三维模型`}
            onClick={() => onActivate(marker.id)}
          >
            <span className="site-marker-pin" aria-hidden="true" />
            <span className="site-marker-label">
              <strong>{marker.label}</strong>
              {marker.description && <small>{marker.description}</small>}
            </span>
          </button>
        ))}
      </div>
      {!ready && !loadError && (
        <div className="site-loading" role="status">
          <div className="site-loading-panel">
            <strong>正在加载{site.name}</strong>
            <div className={`site-loading-track${preparing || progress === null ? ' is-indeterminate' : ''}`} role="progressbar" aria-label="场地模型加载进度" aria-valuemin={0} aria-valuemax={100} aria-valuenow={preparing || progress === null ? undefined : Math.round(progress)} aria-valuetext={preparing ? '正在准备场景' : progress === null ? '正在下载模型' : undefined}>
              <span style={preparing || progress === null ? undefined : { width: `${progress}%` }} />
            </div>
            <span>{preparing ? '正在准备场景' : progress === null ? '正在下载模型' : `${Math.round(progress)}%`}</span>
          </div>
        </div>
      )}
      {loadError && (
        <div className="site-error" role="alert">
          {site.poster && <img src={resolveAssetUrl(site.poster)} alt="" />}
          <strong>场地模型加载失败</strong>
          <span>{loadError}</span>
          <button type="button" onClick={() => setRetryAttempt(value => value + 1)}>重新加载</button>
        </div>
      )}
    </div>
  );
});
