import { ChevronRight, Compass, Crosshair, Maximize, Pause, Play, RotateCcw } from 'lucide-react';
import { useCallback, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { resolveAssetUrl } from '../../config/loadConfig';
import type { SiteModelConfig } from '../../config/schema';
import { hasWebGLSupport } from '../../shared/webgl';
import { SiteScene, type SiteMarkerConfig, type SiteSceneComponent, type SiteViewState } from './SiteScene';
import './site.css';

export interface SitePageProps {
  SceneComponent?: SiteSceneComponent;
  supportsWebGL?: () => boolean;
}

function DeviceIndex({ site, onOpen }: { site: SiteModelConfig | undefined; onOpen(deviceId: string): void }) {
  const { config } = useMuseumConfig();
  return (
    <section className="site-explorer">
      <header className="feature-hero compact">
        <span>EQUIPMENT</span>
        <h1>{site?.name ?? '设备模型'}</h1>
        <p>{site?.summary || '选择一台设备查看三维模型。'}</p>
      </header>
      <div className="site-index-list">
        {config.devices.map(device => (
          <button type="button" key={device.id} className="site-index-card" onClick={() => onOpen(device.id)}>
            <img src={resolveAssetUrl(device.poster)} alt="" loading="lazy" decoding="async" />
            <span>
              <strong>{device.name}</strong>
              <small>{device.parts.length ? `${device.parts.length} 个可识别部件` : '整机查看'}</small>
            </span>
            <ChevronRight aria-hidden="true" />
          </button>
        ))}
        {config.devices.length === 0 && <p className="site-empty">配置里还没有设备。</p>}
      </div>
    </section>
  );
}

export function SitePage({ SceneComponent = SiteScene, supportsWebGL = hasWebGLSupport }: SitePageProps) {
  const navigate = useNavigate();
  const { config } = useMuseumConfig();
  const site = config.siteModel;
  const [webglAvailable] = useState(() => supportsWebGL());
  const [view, setView] = useState<SiteViewState>({ reset: 0, rotate: false, top: false, focus: null });
  const [issues, setIssues] = useState(0);

  const markers = useMemo<SiteMarkerConfig[]>(() => (site?.hotspots ?? []).map(hotspot => {
    const device = config.devices.find(item => item.id === hotspot.deviceId);
    return {
      id: hotspot.id,
      label: hotspot.label || device?.name || hotspot.deviceId,
      // 标记只显示设备名：副标题来自配置，实测手机上两行标签把画面压得很乱，
      // 而且内容通常与设备名重复（"库外试验场内的工频试验成套装置"）。
      description: hotspot.description ?? '',
    };
  }), [site, config.devices]);

  const activate = useCallback((hotspotId: string) => {
    const hotspot = site?.hotspots.find(item => item.id === hotspotId);
    if (hotspot) navigate(`/devices/${hotspot.deviceId}`);
  }, [navigate, site]);

  if (!site) return <DeviceIndex site={site} onOpen={id => navigate(`/devices/${id}`)} />;

  return (
    <section className="site-explorer has-stage">
      <div className="site-studio">
        {webglAvailable ? (
          <SceneComponent
            site={site}
            markers={markers}
            view={view}
            onActivate={activate}
            onIssues={setIssues}
          />
        ) : (
          <div className="site-webgl-fallback">
            <img src={resolveAssetUrl(site.poster)} alt={`${site.name}静态预览`} />
            <strong>三维查看暂不可用</strong>
            <p>仍可从下面的设备列表进入每一台设备的详情。</p>
          </div>
        )}
        <div className="site-vignette" aria-hidden="true" />
        {/* 顶部柔光衬底：让标题/提示背后的背景恒定，进场时不会显得"文字也在糊→清"（见 site.css） */}
        <div className="site-haze" aria-hidden="true" />

        {/*
          头部一行：左边身份（场域名），右边工具圆钮，与设备模型页、地图页同一结构：
          标题行固定行高（--page-head-title-line），右上角工具与它共用一条中线；
          其它信息一律绝对定位在下方，不参与居中计算。
          眉标"场地模型"已去掉：底部导航已经写着栏目名，这一行不必再重复一次。
        */}
        <div className="site-header">
          <header className="site-identity">
            <h1>{site.name}</h1>
            {/* 这里只留"这是哪、叫什么"。场地简介、三角面数、操作说明都去过：
                模型信息属于内部资料，不该占手机首屏。 */}
            {issues > 0 && <small className="site-issue">{issues} 个设备锚点未在场地模型中找到，标记位置可能不准</small>}
          </header>

          <nav className="site-tools" aria-label="场地视角">
            <button
              type="button"
              aria-label={view.rotate ? '暂停自动旋转' : '自动旋转'}
              aria-pressed={view.rotate}
              className={view.rotate ? 'is-active' : ''}
              onClick={() => setView(current => ({ ...current, rotate: !current.rotate }))}
            >
              {view.rotate ? <Pause /> : <Play />}
            </button>
            <button
              type="button"
              aria-label={view.top ? '回到默认视角' : '俯视全场'}
              aria-pressed={view.top}
              className={view.top ? 'is-active' : ''}
              onClick={() => setView(current => ({ ...current, top: !current.top }))}
            >
              <Compass />
            </button>
            <button type="button" aria-label="复位视角" onClick={() => setView(current => ({ ...current, reset: current.reset + 1, top: false, focus: null }))}><RotateCcw /></button>
            <button type="button" aria-label="全屏查看" onClick={() => {
              const studio = document.querySelector<HTMLElement>('.site-studio');
              if (studio?.requestFullscreen) void studio.requestFullscreen();
            }}><Maximize /></button>
          </nav>
        </div>

        <ul className="site-device-rail" aria-label="场地中的设备">
          {markers.map(marker => {
            const hotspot = site.hotspots.find(item => item.id === marker.id);
            const device = config.devices.find(item => item.id === hotspot?.deviceId);
            if (!device) return null;
            return (
              <li key={marker.id} className="site-device-card">
                <button type="button" className="site-device-open" onClick={() => activate(marker.id)}>
                  <img src={resolveAssetUrl(device.poster)} alt="" loading="lazy" decoding="async" />
                  <span>
                    <strong>{device.name}</strong>
                    <small>{device.parts.length ? `${device.parts.length} 个可识别部件` : '整机查看'}</small>
                  </span>
                  <ChevronRight aria-hidden="true" />
                </button>
                <button
                  type="button"
                  className="site-device-locate"
                  aria-label={`在场地中定位${device.name}`}
                  onClick={() => setView(current => ({ ...current, focus: current.focus === marker.id ? null : marker.id }))}
                >
                  <Crosshair />
                </button>
              </li>
            );
          })}
        </ul>

        <footer className="site-footer">
          <span>库外试验场 <b>·</b> {markers.length} 台设备可查看</span>
          {config.devices.length > markers.length && <span>另有 {config.devices.length - markers.length} 台设备未在场地中标点</span>}
        </footer>
      </div>
    </section>
  );
}

export default SitePage;
